import {pinVoltage,poweredDevice,logic} from './bus-electrical.js';import {TFTController} from './tft-controller.js';
export function stampTFT(c,{net,branch,sensors,addNode}){
 if(c.type==='hc4050'){branch(c.id+':load',net(c,'VCC'),net(c,'GND'),100000);for(let i=1;i<=6;i++)sensors.push({id:c.id+':Y'+i,vcc:net(c,'VCC'),gnd:net(c,'GND'),out:addNode(net(c,'Y'+i)),min:2,max:6,ohms:50,compute:(s,v,g)=>{const a=s.voltages.get(net(c,'A'+i)),supply=v-g;if(!Number.isFinite(a)||a-g<0||a-g>15)return null;return a-g>=.7*supply?v:a-g<=.3*supply?g:null;}});return true;}
 if(c.type==='tft7735'||c.type==='tft7789'||c.type==='ili9341'){branch(c.id+':logic-load',net(c,'VCC'),net(c,'GND'),1000);branch(c.id+':backlight',net(c,'BL'),net(c,'GND'),330);return true;}return false;
}
export function attachTFTRuntime(runtime,engine,initial){let project=initial,states=new Map(),disposed=false,busy=false;
 const refresh=()=>{if(disposed||busy)return;busy=true;try{for(const d of states.values()){const dc=engine.solution,p=poweredDevice(dc,d.id,{min:d.type==='tft7735'?2.6:2.4,max:3.6}),pins=Object.fromEntries(['SCK','MOSI','CS','DC','RST','BL'].map(pin=>[pin,pinVoltage(dc,d.id,pin)])),over=Object.values(pins).some(v=>Number.isFinite(v)&&v>p.voltage+.3),powered=p.powered&&!over,levels=Object.fromEntries(Object.entries(pins).map(([k,v])=>[k,logic(v,p.voltage)]));
  if(d.powered&&!powered)d.controller.reset(true,runtime.cpu.cycles);d.powered=powered;d.overvoltage=over;d.backlight=levels.BL===true;d.connected=powered&&['SCK','MOSI','CS','DC','RST'].every(k=>levels[k]!==null);
  if(powered){if(levels.RST===false&&!d.resetLow)d.controller.reset(true,runtime.cpu.cycles);d.resetLow=levels.RST===false;if(levels.CS!==false||d.resetLow){d.bits=0;d.shift=0;}else if(levels.SCK===true&&d.sck===false){if(levels.MOSI===null){d.bits=0;d.controller.errors++;}else{d.shift=(d.shift<<1)|(levels.MOSI?1:0);if(++d.bits===8){d.controller.byte(d.shift,levels.DC===true,runtime.cpu.cycles);d.bytes++;d.bits=0;d.shift=0;}}}}
  d.sck=levels.SCK;
 }}finally{busy=false;}};
 const reconcile=()=>{const ids=new Set();for(const c of project.components.filter(c=>['tft7735','tft7789','ili9341'].includes(c.type))){ids.add(c.id);if(!states.has(c.id))states.set(c.id,{id:c.id,type:c.type,controller:new TFTController(c.type),bits:0,shift:0,bytes:0,powered:false,sck:null,reported:-1,crop:''});}for(const id of states.keys())if(!ids.has(id))states.delete(id);refresh();};reconcile();const unsubscribe=engine.subscribe(refresh);
 return{updateProject(next){project=next;reconcile();},snapshot(){refresh();const modules={};for(const d of states.values()){const c=project.components.find(c=>c.id===d.id),t=d.controller,crop=[c.params.offsetX??0,c.params.offsetY??0].join(','),changed=t.revision!==d.reported||crop!==d.crop;modules[d.id]={type:d.type,powered:d.powered,connected:d.connected,overvoltage:d.overvoltage,visible:d.powered&&d.backlight&&!t.sleep&&t.on&&runtime.cpu.cycles>=t.readyAt,writes:t.writes,errors:t.errors,bytes:d.bytes,format:t.format,madctl:t.madctl,revision:t.revision,crop,...(changed?{frame:t.frame(c.params.offsetX??0,c.params.offsetY??0)}:{})};d.reported=t.revision;d.crop=crop;}return{modules};},dispose(){disposed=true;unsubscribe();}};
}
